package com.aicharacter.v3;
/** Couples ground contact, pelvis, spine, shoulders and head into one locomotor pose. */
public final class WholeBodyMotorEngine{private WholeBodyMotorEngine(){}
 public static void advance(WorldState s,double dt){if(s==null||dt<=0)return;if(s.bodyRig==null)s.bodyRig=new BodyRigState();BodyRigState r=s.bodyRig;PhysicsBodyState p=s.girlPhysics;BodyInstinctState b=s.bodyInstinct;double speed=s.girlTravel!=null&&s.girlTravel.active?s.girlTravel.lastSpeed:0;double gait=Math.max(0,Math.min(1,speed/92.0));double total=s.girlTravel==null?0:Math.max(0,s.girlTravel.distanceTravelled);if(total+1e-6<r.lastDistanceSample)r.lastDistanceSample=0;double travelled=Math.max(0,total-r.lastDistanceSample);r.lastDistanceSample=total;double stridePx=WorldUnits.mToPx(.62);r.stridePhase=(r.stridePhase+travelled/Math.max(1,stridePx))%1.0;double wave=Math.sin(r.stridePhase*Math.PI*2);double imbalance=p==null?0:(1-p.balance);double guard=b==null?0:b.guarding,breath=b==null?0:b.breathDrive,fatigue=b==null?0:b.fatigueDroop;
  double load=.5+wave*.32*gait;double lp=s.localizedPain==null?0:s.localizedPain.leftLeg,rp=s.localizedPain==null?0:s.localizedPain.rightLeg,avoid=(lp-rp)*.28;r.leftLegLoad=clamp(load-avoid,.08,.92);r.rightLegLoad=clamp(1-load+avoid,.08,.92);double norm=Math.max(.01,r.leftLegLoad+r.rightLegLoad);r.leftLegLoad/=norm;r.rightLegLoad/=norm;double contactWave=Math.sin(r.stridePhase*Math.PI*2);r.leftFootContact=gait<.08?1:(contactWave>-.18?1:0);r.rightFootContact=gait<.08?1:(contactWave<.18?1:0);double gx=s.haruX;if(!Double.isFinite(r.leftFootWorldX))r.leftFootWorldX=gx-.14*WorldUnits.PIXELS_PER_METER;if(!Double.isFinite(r.rightFootWorldX))r.rightFootWorldX=gx+.14*WorldUnits.PIXELS_PER_METER;if(r.leftFootContact<.5)r.leftFootWorldX=gx+wave*.28*(1-lp*.42)*WorldUnits.PIXELS_PER_METER;if(r.rightFootContact<.5)r.rightFootWorldX=gx-wave*.28*(1-rp*.42)*WorldUnits.PIXELS_PER_METER;r.leftFootGroundY=GroundGeometry.heightPx(s,r.leftFootWorldX);r.rightFootGroundY=GroundGeometry.heightPx(s,r.rightFootWorldX);r.groundSlope=GroundGeometry.slope(s,gx);
  r.pelvisTilt=wave*.045*gait+(lp-rp)*.055+imbalance*.06+clamp(r.groundSlope,-.35,.35)*.16;r.spineLean=clamp(gait*.035+fatigue*.09+guard*.07,-.12,.18);r.shoulderCounter=-wave*.10*gait-guard*.08;r.headStabilization=clamp(-r.spineLean*.55-breath*.015,-.10,.10);r.stanceWidth=clamp(.48+imbalance*.22+guard*.10,.35,.82);if(p!=null){double half=.12+r.stanceWidth*.18;double margin=(r.leftFootContact+r.rightFootContact>1.5)?half:half*.48;p.supportLeft=-margin;p.supportRight=margin;double edge=Math.max(0,Math.abs(p.centerOfMassX)-margin*.72);r.recoveryStep=clamp(edge/Math.max(.06,margin),0,1);if(r.recoveryStep>.05){double widen=r.recoveryStep*.11;p.supportLeft-=widen;p.supportRight+=widen;}double locomotorShift=wave*.10*gait;double protectiveShift=-Math.signum(wave)*guard*.035;p.centerOfMassX=locomotorShift+protectiveShift+r.pelvisTilt*.22;}
 }
 private static double clamp(double v,double a,double b){return Math.max(a,Math.min(b,v));}
}